function RequestDetailView({ requestId, draft }: { requestId: string; draft: boolean }) {
  const { t, i18n } = useTranslation('services');
  const display = useDisplayDictionary();
  const toast = useToast();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const submitDraft = useProductActionMutation('route.services.work.draft-submit.action');
  const cancelRequest = useProductActionMutation('route.services.work.request-cancel.action');
  const [confirmCancel, setConfirmCancel] = useState(false);
  const [editing, setEditing] = useState(false);
  const requestScope = useProductSurfaceRequestScope({
    productKey: 'services',
    surfaceKey: 'services.work',
  });
  const detailKey = [
    'services',
    'request',
    requestId,
    'view',
    draft ? 'draft' : 'absent',
    ...requestScope.cacheKey,
  ];
  const detail = useQuery({
    queryKey: detailKey,
    queryFn: ({ signal }) =>
      draft
        ? getServiceDraftRequest(requestId, signal)
        : getServiceMyRequest(requestId, signal, requestScope.contextScopeKey),
    enabled: requestScope.ready,
    meta: requestScope.queryMeta,
    retry: 1,
  });
  const mutation = useMutation({
    mutationFn: ({
      operation,
      data,
    }: {
      operation: 'submit' | 'cancel';
      data: ServiceRequestDetail;
    }) =>
      operation === 'submit'
        ? submitDraft((authority) =>
            submitServiceDraft(data.request.requestId, data.request.version, authority)
          )
        : cancelRequest((authority) =>
            cancelServiceRequest(data.request.requestId, data.request.version, authority)
          ),
    onSuccess: async (data, input) => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ['services', 'requests'] }),
        queryClient.invalidateQueries({ queryKey: ['services', 'request', requestId] }),
      ]);
      toast.success(
        t(input.operation === 'submit' ? 'detail.submittedSuccess' : 'detail.cancelledSuccess')
      );
      setConfirmCancel(false);
      navigate(
        `/services/${input.operation === 'submit' ? 'my' : 'drafts'}/${data.request.requestId}`
      );
    },
    onError: (error) => toast.error(serviceRequestErrorText(error, t('detail.actionError'))),
  });
  const data = detail.data;
  const keepDraftOnRefreshError = Boolean(
    data && (!(detail.error instanceof HttpError) || detail.error.status >= 500)
  );
  const fieldByKey = new Map((data?.requestSchema.fields ?? []).map((field) => [field.key, field]));
  const backPath = data?.request.status === 'DRAFT' ? '/services/drafts' : '/services/my';
  const cancellable = data && ['DRAFT', 'SUBMITTED', 'TRIAGED'].includes(data.request.status);

  return (
    <PageCanvas>
      <Box sx={{ py: { xs: 3, md: 4 } }}>
        <ActionButton
          component={Link}
          to={backPath}
          intent="quiet"
          startIcon={<ArrowLeft size={17} />}
          sx={{ mb: 2 }}
        >
          {t('detail.back')}
        </ActionButton>
        {detail.isError && !keepDraftOnRefreshError ? (
          <Alert severity="error">
            {serviceRequestErrorText(detail.error, t('detail.loadError'))}
          </Alert>
        ) : !data ? (
          <Skeleton variant="rounded" height={420} />
        ) : (
          <Stack gap={3}>
            {detail.isError && (
              <InlineFeedback severity="warning">
                {t('informationResponse.refreshFailed')}
                <ActionButton
                  intent="quiet"
                  disabled={detail.isFetching}
                  onClick={() => void detail.refetch()}
                >
                  {t('informationResponse.refresh')}
                </ActionButton>
              </InlineFeedback>
            )}
            <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" gap={2}>
              <Box>
                <Stack direction="row" alignItems="center" gap={1} flexWrap="wrap">
                  <Typography variant="overline" color="primary.main">
                    {data.request.requestNumber}
                  </Typography>
                  <StatusChip status={data.request.status} />
                </Stack>
                <Typography component="h1" variant="h3" sx={{ mt: 0.5 }}>
                  {serviceRequestName(data.request, i18n.resolvedLanguage ?? i18n.language)}
                </Typography>
                <Typography variant="body1" color="text.secondary" sx={{ mt: 0.75 }}>
                  {data.request.summary}
                </Typography>
              </Box>
              <Stack direction="row" gap={1} alignItems="flex-start">
                {data.request.status === 'DRAFT' && (
                  <>
                    <ActionButton
                      intent="primary"
                      startIcon={<PencilLine size={17} />}
                      onClick={() => setEditing(true)}
                      disabled={mutation.isPending}
                    >
                      {t('detail.editDraft')}
                    </ActionButton>
                    <ActionButton
                      intent="secondary"
                      onClick={() => mutation.mutate({ operation: 'submit', data })}
                      disabled={mutation.isPending}
                    >
                      {t('detail.submitDraft')}
                    </ActionButton>
                  </>
                )}
                {cancellable && (
                  <ActionButton
                    intent="secondary"
                    onClick={() => setConfirmCancel(true)}
                    disabled={mutation.isPending}
                  >
                    {t('detail.cancelRequest')}
                  </ActionButton>
                )}
              </Stack>
            </Stack>
            <ServiceInformationResponse
              key={data.request.requestId}
              detail={data}
              onRefresh={() => void detail.refetch()}
              onConfirmed={(receipt) => {
                queryClient.setQueryData(detailKey, receipt);
                void queryClient.invalidateQueries({ queryKey: ['services', 'requests'] });
              }}
            />
            <Box
              sx={{
                display: 'grid',
                gridTemplateColumns: { xs: '1fr', lg: 'minmax(0, 1.35fr) minmax(320px, .65fr)' },
                gap: 3,
              }}
            >
              <Stack gap={3}>
                <Box
                  component="section"
                  sx={{
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1,
                    bgcolor: 'background.paper',
                  }}
                >
                  <Typography
                    component="h2"
                    variant="subtitle1"
                    fontWeight={800}
                    sx={{ px: 2.5, py: 2 }}
                  >
                    {t('detail.overview')}
                  </Typography>
                  <Divider />
                  <Box
                    sx={{
                      p: 2.5,
                      display: 'grid',
                      gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, 1fr)' },
                      gap: 2.5,
                    }}
                  >
                    {[
                      [t('detail.assignedGroup'), data.request.assignedGroup, UsersRound],
                      [
                        t('detail.assignedTo'),
                        data.request.assignedTo || t('detail.unassigned'),
                        LifeBuoy,
                      ],
                      [
                        t('detail.updated'),
                        formatDate(data.request.updatedAt, {
                          dateStyle: 'medium',
                          timeStyle: 'short',
                        }),
                        Clock3,
                      ],
                      [
                        t('detail.slaDue'),
                        data.request.slaDueAt
                          ? formatDate(data.request.slaDueAt, {
                              dateStyle: 'medium',
                              timeStyle: 'short',
                            })
                          : '—',
                        CalendarDays,
                      ],
                    ].map(([label, value, Icon]) => (
                      <Stack key={String(label)} direction="row" gap={1.25} alignItems="flex-start">
                        <Box sx={{ mt: 0.25, color: 'text.secondary' }}>
                          <Icon size={18} />
                        </Box>
                        <Box>
                          <Typography variant="caption" color="text.secondary">
                            {label as string}
                          </Typography>
                          <Typography variant="body2" fontWeight={650}>
                            {value as string}
                          </Typography>
                        </Box>
                      </Stack>
                    ))}
                  </Box>
                </Box>
                <Box
                  component="section"
                  sx={{
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1,
                    bgcolor: 'background.paper',
                  }}
                >
                  <Typography
                    component="h2"
                    variant="subtitle1"
                    fontWeight={800}
                    sx={{ px: 2.5, py: 2 }}
                  >
                    {t('detail.requestData')}
                  </Typography>
                  <Divider />
                  <Box
                    component="dl"
                    sx={{
                      m: 0,
                      p: 2.5,
                      display: 'grid',
                      gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, 1fr)' },
                      gap: 2.5,
                    }}
                  >
                    {Object.entries(data.values).map(([key, value]) => {
                      const field = fieldByKey.get(key);
                      return (
                        <Box key={key}>
                          <Typography component="dt" variant="caption" color="text.secondary">
                            {field
                              ? serviceRequestFieldLabel(
                                  field,
                                  i18n.resolvedLanguage ?? i18n.language
                                )
                              : key}
                          </Typography>
                          <Typography
                            component="dd"
                            variant="body2"
                            sx={{ m: 0, mt: 0.5, whiteSpace: 'pre-wrap' }}
                          >
                            {typeof value === 'boolean'
                              ? t(value ? 'requestDialog.booleanYes' : 'requestDialog.booleanNo')
                              : String(value)}
                          </Typography>
                        </Box>
                      );
                    })}
                  </Box>
                </Box>
              </Stack>
              <Box
                component="section"
                sx={{ borderLeft: { lg: 1 }, borderColor: 'divider', pl: { lg: 3 } }}
              >
                <Typography component="h2" variant="subtitle1" fontWeight={800}>
                  {t('detail.timeline')}
                </Typography>
                <Stack component="ol" gap={0} sx={{ mt: 2, p: 0, m: 0, listStyle: 'none' }}>
                  {data.timeline.map((event, index) => (
                    <Box
                      component="li"
                      key={event.eventId}
                      sx={{
                        position: 'relative',
                        display: 'grid',
                        gridTemplateColumns: '24px minmax(0, 1fr)',
                        gap: 1.5,
                        pb: 3,
                      }}
                    >
                      {index < data.timeline.length - 1 && (
                        <Box
                          aria-hidden="true"
                          sx={{
                            position: 'absolute',
                            top: 20,
                            bottom: 0,
                            left: 11,
                            width: 1,
                            bgcolor: 'divider',
                          }}
                        />
                      )}
                      <Box
                        aria-hidden="true"
                        sx={{
                          zIndex: 1,
                          width: 24,
                          height: 24,
                          display: 'grid',
                          placeItems: 'center',
                          borderRadius: '50%',
                          color: index === 0 ? 'success.main' : 'text.secondary',
                          bgcolor: 'background.paper',
                          border: 1,
                          borderColor: index === 0 ? 'success.main' : 'divider',
                        }}
                      >
                        {index === 0 ? <CheckCircle2 size={14} /> : <Clock3 size={13} />}
                      </Box>
                      <Box>
                        <Typography variant="body2" fontWeight={750}>
                          {display('auditActions', event.eventType)}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          {formatDate(event.occurredAt, {
                            dateStyle: 'medium',
                            timeStyle: 'short',
                          })}
                        </Typography>
                        {event.note && (
                          <Typography variant="body2" sx={{ mt: 0.75 }}>
                            {event.note}
                          </Typography>
                        )}
                      </Box>
                    </Box>
                  ))}
                </Stack>
              </Box>
            </Box>
          </Stack>
        )}
        <ConfirmDialog
          open={confirmCancel}
          title={t('detail.confirmCancel')}
          description={t('detail.confirmCancelDescription')}
          cancelLabel={t('detail.cancel')}
          confirmLabel={t('detail.confirm')}
          onClose={() => setConfirmCancel(false)}
          onConfirm={() => data && mutation.mutate({ operation: 'cancel', data })}
          busy={mutation.isPending}
          intent="danger"
        />
        <ServiceRequestDialog
          service={null}
          draft={editing && data?.request.status === 'DRAFT' ? data : null}
          onClose={() => setEditing(false)}
        />
      </Box>
    </PageCanvas>
  );
}

export default function ServicesPage() {
  const { view = 'discover', requestId } = useParams();
  if (requestId) return <RequestDetailView requestId={requestId} draft={view === 'drafts'} />;
  if (view === 'my') return <RequestsView drafts={false} />;
  if (view === 'drafts') return <RequestsView drafts />;
  return <DiscoverView />;
}
